#!/usr/bin/env node
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { resolve } from "node:path";

const repoRoot = resolve("/Users/serro/Documents/dev/n/worktrees/superfunctions/publish-mdfn-mailfn-20260902");
const tarballDir = "/tmp/sf-release-tarballs";
mkdirSync(tarballDir, { recursive: true });

const SKIP = new Set(["mdfn/components-react", "mdfn/components-svelte", "mdfn/components-solid"]);
const INTERNAL_PREFIXES = ["@mdfn/", "@mailfn/", "mdfn", "mailfn"];

function run(command, args, cwd) {
  const result = spawnSync(command, args, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] });
  return result;
}

function must(command, args, cwd) {
  const result = run(command, args, cwd);
  if (result.status !== 0) {
    const output = `${result.stdout}\n${result.stderr}`.trim();
    throw new Error(`${command} ${args.join(" ")}\n${output}`);
  }
  return result.stdout.trim();
}

function tarballFor(name) {
  const filename = `${name.replace(/^@/, "").replace("/", "-")}-0.1.0.tgz`;
  const path = resolve(tarballDir, filename);
  return existsSync(path) ? path : null;
}

function rewriteInternalDeps(manifest) {
  let changed = false;
  for (const section of ["dependencies", "devDependencies", "optionalDependencies", "peerDependencies"]) {
    const deps = manifest[section];
    if (!deps) continue;
    for (const [name, spec] of Object.entries(deps)) {
      const isInternal = name === "mdfn" || name === "mailfn" || name.startsWith("@mdfn/") || name.startsWith("@mailfn/");
      if (!isInternal) continue;
      const tarball = tarballFor(name);
      if (!tarball) {
        throw new Error(`missing tarball for internal dependency ${name} (spec ${spec})`);
      }
      deps[name] = tarball;
      changed = true;
    }
  }
  return changed;
}

function validate(packagePath) {
  const abs = resolve(repoRoot, packagePath);
  const packageJsonPath = resolve(abs, "package.json");
  const original = readFileSync(packageJsonPath, "utf8");
  const manifest = JSON.parse(original);
  console.log(`\n======== ${manifest.name} (${packagePath}) ========`);
  try {
    rewriteInternalDeps(manifest);
    writeFileSync(packageJsonPath, `${JSON.stringify(manifest, null, 2)}\n`);
    must("rm", ["-rf", "node_modules", "dist"], abs);
    must("npm", ["install", "--workspaces=false", "--package-lock=false"], abs);
    writeFileSync(packageJsonPath, original);
    must("npm", ["run", "build"], abs);
    must("npm", ["test"], abs);
    must("npm", ["pack", "--dry-run"], abs);
    const packed = must("npm", ["pack", "--pack-destination", tarballDir], abs).split("\n").pop();
    console.log(`OK ${manifest.name} packed ${packed}`);
  } catch (error) {
    writeFileSync(packageJsonPath, original);
    console.error(`FAIL ${manifest.name}`);
    throw error;
  } finally {
    writeFileSync(packageJsonPath, original);
  }
}

const packages = process.argv.slice(2);
for (const packagePath of packages) {
  if (SKIP.has(packagePath)) {
    console.log(`SKIP ${packagePath}`);
    continue;
  }
  validate(packagePath);
}
console.log("\nALL REQUESTED PACKAGES VALIDATED");

