    throw new Error(`${command} ${args.join(" ")}\n${output}`);
  }
  return result.stdout.trim();
}

function isInternal(name) {
  return (
    name === "sendfn" ||
    name === "mailfn" ||
    name.startsWith("@uifn/") ||
    name.startsWith("@mdfn/") ||
    name.startsWith("@mailfn/") ||
    name.startsWith("@sendfn/")
  );
}

function tarballFor(name) {
  const prefix = `${name.replace(/^@/, "").replace("/", "-")}-`;
  const matches = existsSync(tarballDir)
    ? readdirSync(tarballDir).filter((file) => file.startsWith(prefix) && file.endsWith(".tgz"))
    : [];
  if (matches.length === 0) return null;
  matches.sort();
  return resolve(tarballDir, matches[matches.length - 1]);
}

function rewriteInternalDeps(manifest) {
  const overrides = { ...(manifest.overrides ?? {}) };
  for (const section of ["dependencies", "devDependencies", "optionalDependencies"]) {
    const deps = manifest[section];
    if (!deps) continue;
    for (const [name, spec] of Object.entries(deps)) {
      if (!isInternal(name)) continue;
      const tarball = tarballFor(name);
      if (tarball) {
        deps[name] = tarball;
        overrides[name] = tarball;
        continue;
      }
      const published = run("npm", ["view", `${name}@${spec}`, "version"], repoRoot);
      if (published.status !== 0) {
        throw new Error(`internal dependency ${name}@${spec} is not on npm and has no local tarball`);
      }
    }
  }
  if (Object.keys(overrides).length) manifest.overrides = overrides;
}

function validate(packagePath) {
  const abs = resolve(repoRoot, packagePath);
  const packageJsonPath = resolve(abs, "package.json");
  const original = readFileSync(packageJsonPath, "utf8");
  const manifest = JSON.parse(original);
  console.log(`\n======== ${manifest.name}@${manifest.version} (${packagePath}) ========`);
  try {
    rewriteInternalDeps(manifest);
    writeFileSync(packageJsonPath, `${JSON.stringify(manifest, null, 2)}\n`);
    must("rm", ["-rf", "node_modules", "dist"], abs);
    must("npm", ["install", "--workspaces=false", "--package-lock=false"], abs);
    writeFileSync(packageJsonPath, original);
    must("npm", ["run", "build"], abs);
    must("npm", ["test"], abs);
    must("npm", ["pack", "--dry-run"], abs);
    const packed = must("npm", ["pack", "--pack-destination", tarballDir], abs).split("\n").pop();
    console.log(`OK ${manifest.name} packed ${basename(String(packed).trim())}`);
  } catch (error) {
    writeFileSync(packageJsonPath, original);
    console.error(`FAIL ${manifest.name}`);
    throw error;
  } finally {
    writeFileSync(packageJsonPath, original);
  }
}

const packages = process.argv.slice(2);
